import AVFoundation

/// The MixAI brand sound, once per cold start of the Apple TV app (WP22-10, ADR-0016: on by default on TV apps, with
/// a setting to turn it off). `Resources/brand-signature.wav` is generated by `brand/scripts/build.mjs`.
///
/// It plays in the `.ambient` category, so it mixes with whatever another app is already playing instead of stopping
/// it. The playback category that films and music need is put back when the sound ends, or earlier when playback starts.
@MainActor
enum TVStartupSound {
    private static var player: AVAudioPlayer?
    private static var done = false

    static func playOnce() {
        guard !done else { return }
        done = true
          guard TVPrefs.startupSound,
              let url = Bundle.main.url(forResource: "brand-signature", withExtension: "wav"),
              let p = try? AVAudioPlayer(contentsOf: url) else { return }
        let session = AVAudioSession.sharedInstance()
        do {
            try session.setCategory(.ambient, mode: .default)
            try session.setActive(true)
        } catch {
            restoreSession()
            return
        }
        guard p.play() else { restoreSession(); return }
        player = p
        let length = p.duration
        Task {
            // Wait for the last sample (bounded: a stalled output must not keep the player alive), then release it.
            let deadline = Date.now.addingTimeInterval(length + 2)
            while player?.isPlaying == true, Date.now < deadline {
                try? await Task.sleep(for: .milliseconds(100))
            }
            finish()
        }
    }

    /// Stops the sound if it still plays, releases the player and gives the audio session back to films and music.
    /// Does nothing when the sound is not playing, so playback code can call it before it starts.
    static func finish() {
        guard let p = player else { return }
        player = nil
        p.stop()
        restoreSession()
    }

    private static func restoreSession() {
        let session = AVAudioSession.sharedInstance()
        // Deactivate first: switching an active session to a category that does not mix would cut another app's audio.
        try? session.setActive(false, options: .notifyOthersOnDeactivation)
        try? session.setCategory(.playback, mode: .moviePlayback)
    }
}
